// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        uint256 contractBalanceBefore = address(c).balance;
        uint256 receiverBalanceBefore = receiver.balance;
        vm.prank(address(this));
        bool ok;
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 contractBalanceAfter = address(c).balance;
        uint256 receiverBalanceAfter = receiver.balance;
        assertTrue(!ok || contractBalanceAfter == contractBalanceBefore - amount);
    }
}
